 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width / full-height solid lines are the separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1])
                 for i in range(len(row_bounds) - 1)
                 if row_bounds[i + 1] > row_bounds[i] + 1]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1])
                 for i in range(len(col_bounds) - 1)
                 if col_bounds[i + 1] > col_bounds[i] + 1]

    # The most common color in the cells is the common cell background.
    from collections import Counter
    counts = Counter(grid[r][c] for r0, r1 in row_spans for c0, c1 in col_spans
                     for r in range(r0, r1) for c in range(c0, c1))
    background = counts.most_common(1)[0][0]
    out = [[background for _ in col_spans] for _ in row_spans]
    for i, (r0, r1) in enumerate(row_spans):
        for j, (c0, c1) in enumerate(col_spans):
            non_background = sum(grid[r][c] != background
                                 for r in range(r0, r1) for c in range(c0, c1))
            if non_background == 2:
                out[i][j] = 1
    return out
